```csharp
using UnityEngine;

public class GameController : MonoBehaviour
{
    public GameObject[] Gemmas; // arreglo de Gemmas
    public int Score = 0; // puntaje actual
    public int ScoreMultiplier = 1; // multiplicador de puntaje

    private void Start()
    {
        // inicializar el juego
        Score = 0;
        ScoreMultiplier = 1;

        // inicializar el tableau
        Gemmas = GameObject.FindObjectsOfType<GameObject>(tag: "Gemma");
    }

    private void Update()
    {
        // pulsar un botón para relocar las Gemmas
        if (Input.GetMouseButtonDown(0))
        {
            RelocateGemma();
        }
    }

    private void RelocateGemma()
    {
        // obtener la posicion actual de la Gemma
        RaycastHit2D hit = Physics2D.Raycast(Camera.main.ScreenToWorldPoint(Input.mousePosition), Vector2.zero);
        GameObject gemma = hit.collider.gameObject;

        // verificar si la Gemma puede ser relocada
        if (gemma != null)
        {
            // calcular la nueva posicon de la Gemma
            Vector2 newPostion = gemma.transform.position + new Vector2(Random.Range(-1, 2), Random.Range(-1, 2));

            // verificar si la nueva posición es válida
            if (newPostion.x >= 0 && newPostion.x < Gemmas.Length && newPostion.y >= 0 && newPostion.y < Gemmas.Length)
            {
                // reubicar la Gemma
                Gemmas[(int)newPostion.x][(int)newPostion.y] = gemma;
            }
        }
    }
}
```
