**Paso 6: Creación del sistema de Match-3**

1. Agrega un script `MatchManager.cs` en la carpeta `Scripts` con el siguiente código:
```csharp
using UnityEngine;

public class MatchManager : MonoBehaviour
{
    public GameObject[] Gemmas; // arreglo de Gemmas
    public int Score; // puntaje actual

    private void Update()
    {
        // verificar si hay un Match-3
        if (HasMatch())
        {
            // eliminar las Gemmas del Match-3
            RemoveMatch();

            // actualizar el puntaje
            Score += GetScoreFromMatch();
        }
    }

    private bool HasMatch()
    {
        // comprobar si hay un Match-3 en la tabla
        for (int i = 0; i < Gemmas.Length; i++)
        {
            for (int j = 0; j < Gemmas[i].Length; j++)
            {
                // verificar si la Gemma actual es parte de un Match-3
                if (IsMatch(Gemmas[i][j]))
                {
                    return true;
                }
            }
        }
        return false;
    }

    private bool IsMatch(GameObject gemma)
    {
        // verificar si la Gemma actual es igual a las Gemmas adyacentes
        return Gemmas[(int)gemma.transform.position.x][(int)gemma.transform.position.y] == gemma;
    }

    private void RemoveMatch()
    {
        // eliminar las Gemmas del Match-3
        foreach (GameObject gemma in Gemmas)
        {
            if (gemma == null) continue;

            Gemmas[(int)gemma.transform.position.x][(int)gemma.transform.position.y] = null;
        }
    }

    private int GetScoreFromMatch()
    {
        // calcular el puntaje del Match-3
        return Score * ScoreMultiplier;
    }
}
```
